using System.ComponentModel;
using System.Net;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Provides web search functionality for the research agent.
/// Uses a simple HTTP-based search approach.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Searches the web for information on a given query. Returns a list of search results with titles, snippets, and URLs.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(query);

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encodedQuery = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await HttpClient.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main answer)
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"**{abstractSource}**: {abstractText}\nURL: {abstractUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var relatedTopics)
                && relatedTopics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in relatedTopics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"- {text}\n  URL: {firstUrl}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try rephrasing or searching for related terms.";
            }

            return $"Search results for '{query}':\n\n{string.Join("\n\n", results)}";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

