{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

// Run the agent with streaming output
await foreach (var update in agent.RunStreamingAsync(messages, session: null, options: null))
{
    if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();
logger.LogInformation("Research complete. Notes taken: {Count}", notebook.NoteCount);

